   19	// The one surviving situation for invariant:NAKED_BESIDE_WALLED after the QUAL-DEDUP merge: a naked
   20	// colony, a naked planet and a stationary fleet, each read at the bound and at zero. The live read
   21	// found accounts with planets at zero defence while a sibling held a real wall: the whole wall was
   22	// raised on the planet with the most to lose and the bare siblings were never reached.
   23	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
   24	    $situation = Situation::of($this)
   25	        ->levelEveryPlanet('robot_factory', 2)
   26	        ->levelEveryPlanet('shipyard', 4)
   27	        ->defence('rocket_launcher', 20)
   28	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   29	        ->session();
   30	
   31	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   32	        ->whereKeyNot($this->currentPlanetId)->value('id');
   33	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
   34	
   35	    $situation->expectWork(AiWorkKind::QueueUnits);
   36	
   37	    // A short build may already be complete by the time the session's own clock has advanced to every
   38	    // intent, so the wall counts whether it is standing or still paid for in the yard.
   39	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
   40	});
