   42	// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard), the story the deleted
   43	// NakedColonyWallSituationTest held: the colony below the yard its wall waits on. The cohort read
   44	// found an account holding a wall on one planet while a young colony stood at zero defence: the wall
   45	// waits on a shipyard the colony does not have yet, and the account kept spending its yard elsewhere.
   46	// An account whose sibling already holds a wall has to bring the shipyard and then the wall to the
   47	// bare colony, instead of leaving it naked for as long as it plays.
   48	test('an account whose sibling holds a wall reaches the colony that has no shipyard yet', function (): void {
   49	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
   50	
   51	    $situation = Situation::of($this)
   52	        ->level('robot_factory', 2)
   53	        ->level('shipyard', 4)
   54	        ->defence('rocket_launcher', 30)
   55	        ->colony()
   56	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   57	        ->sessions(8, 30);
   58	
   59	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   60	        ->whereNotIn('id', $before)->value('id');
   61	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
   62	
   63	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'expected the wall on the colony that started without a shipyard; ' . $situation->account());
   64	});
