   66	// The story the deleted NakedPlanetWallFirstTest held: the wall waits on a yard the bare colony does
   67	// not have, so its login has to go to that yard before any wall unit. The marker is the host's own
   68	// prerequisite list for the defence registry, not a facility this file names.
   69	test('a login beside a walled homeworld spends the bare colony on the yard its wall waits on', function (): void {
   70	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
   71	
   72	    $situation = Situation::of($this)
   73	        ->level('robot_factory', 2)
   74	        ->level('shipyard', 4)
   75	        ->ships('small_cargo', 10)
   76	        ->defence('light_laser', 60)
   77	        ->colony()
   78	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000)
   79	        ->session();
   80	
   81	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   82	        ->whereNotIn('id', $before)->value('id');
   83	    $ordered = BuildingQueue::query()->where('planet_id', $colonyId)->where('canceled', 0)
   84	        ->orderBy('id')->value('object_id');
   85	
   86	    expect($ordered)->not->toBeNull('the bare colony got no order this login; ' . $situation->account());
   87	
   88	    $prerequisites = [];
   89	    foreach (ObjectService::getDefenseObjects() as $defence) {
   90	        $prerequisites = [...$prerequisites, ...array_keys(ObjectService::getRecursiveRequirements($defence->machine_name))];
   91	    }
   92	
   93	    $orderedName = ObjectService::getObjectById((int) $ordered)->machine_name;
   94	    expect(in_array($orderedName, $prerequisites, true))->toBeTrue(
   95	        'the bare colony spent its login on ' . $orderedName . ', not on what its wall waits for; ' . $situation->account()
   96	    );
   97	});
