   99	// The story the deleted StationaryFleetWallSituationTest held: what a planet stands to lose is not only
  100	// the output that piles up while the account is away. A fleet left standing in orbit is worth to a
  101	// raider exactly what the pile is, so a wall sized on production alone leaves it uncovered. The plant
  102	// puts the idle fleet on a planet whose small wall already covers the mines, and the record must state
  103	// a need only once the fleet is there.
  104	test('an idle fleet raises what the planet stands to lose', function (): void {
  105	    $situation = Situation::of($this)
  106	        ->resources(1_000_000, 1_000_000, 1_000_000)
  107	        ->level('shipyard', 4)
  108	        ->defence('rocket_launcher', 200);
  109	
  110	    $player = $this->planetService->getPlayer();
  111	    $covered = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
  112	
  113	    expect($covered)->toBeNull('the wall already covers production-only exposure; ' . $situation->account());
  114	
  115	    $situation->ships('light_fighter', 2_000);
  116	
  117	    $exposed = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
  118	
  119	    expect($exposed)->toBeInstanceOf(DefenseNeed::class)
  120	        ->and($exposed->protectedValue)->toBeGreaterThan(0.0)
  121	        ->and($exposed->currentDefenseValue)->toBeGreaterThan(0.0);
  122	});
