214	// The bound at zero: with nothing to build with, the account queues no wall at all -- the host's own
215	// affordability gate is not bypassed to make a naked planet look walled. Read after the merged
216	// stories, so one file carries the rule at the bound, at zero and past it.
217	test('an account that can pay for nothing queues no wall', function (): void {
218	    $situation = Situation::of($this)
219	        ->level('robot_factory', 2)
