254	/** @return list<int> the account's planets (moons excluded) whose built defence columns are all zero */
255	function builtNakedPlanets(int $playerId): array
256	{
257	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
258	
259	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
260	        ->map(static fn ($id): int => (int) $id)
261	        ->filter(static function (int $id) use ($defence): bool {
262	            $row = (array) DB::table('planets')->where('id', $id)->first();
263	            foreach ($defence as $machineName) {
264	                if ((int) ($row[$machineName] ?? 0) > 0) {
265	                    return false;
266	                }
267	            }
268	
269	            return true;
270	        })->values()->all();
271	}
272	
273	/** @return list<int> the account's planets (moons excluded) that hold no defence, ordered or built */
274	function nakedPlanets(int $playerId): array
275	{
276	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
277	        ->map(static fn ($id): int => (int) $id)
278	        ->filter(static function (int $id): bool {
279	            $planet = app(PlanetServiceFactory::class)->make($id, true);
280	
281	            return $planet === null || app(DefenseNeedEvaluator::class)->standingUnits($planet) === 0;
282	        })->values()->all();
283	}
284	
285	/** The defence units the account stands on its planets. */
286	function standingDefence(int $playerId): int
287	{
288	    $total = 0;
289	
290	    foreach (Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id') as $planetId) {
291	        $planet = app(PlanetServiceFactory::class)->make((int) $planetId, true);
292	        $total += $planet === null ? 0 : $planet->getDefenseUnits()->getAmount();
293	    }
294	
295	    return $total;
296	}

