    3	namespace Modules\AI\Domain\Decision;
    4	
    5	use Modules\AI\Enums\AiActivityBand;
    6	use Modules\AI\Models\AiProfile;
    7	use OGame\GameObjects\Models\Units\UnitCollection;
    8	use OGame\Models\Resources;
    9	use OGame\Models\UnitQueue;
   10	use OGame\Services\FleetMissionService;
   11	use OGame\Services\ObjectService;
   12	use OGame\Services\PlanetService;
   13	use OGame\Services\PlayerService;
   14	use Symfony\Component\Yaml\Yaml;
   15	
   16	/**
   17	 * Whether this planet wants a wall at all, and how big: the size half of the defence decision.
   18	 *
   19	 * `DefenseCompositionPlanner` decides what shape the wall takes; this decides whether there is
   20	 * anything worth defending and how much. What a raider weighs is the pile on the planet and the
   21	 * production that accrues there while the account is away, both in the one currency the game prices
   22	 * everything in, and that value is what the wall is sized to. The doctrine never enters here: it
   23	 * picks the shape, not the size, so a Minimalist and a Bunker are handed the same size and build it
   24	 * differently.
   25	 *
   26	 * Two things decide the number, both host state the module already reads. Presence: the account's
   27	 * own `activity_band` is how often it looks in, so a band that visits once a day leaves a planet's
   28	 * output standing far longer than one that looks every few hours and is exposed to more of it.
   29	 * Contact: a pile only counts once the account has been seen -- an unmolested account spends its
   30	 * surplus rather than standing a wall against it (decision doctrine D10, spend-first) -- but once the
   31	 * host reports a hostile inbound there is no time left to spend it, so the whole pile joins what the
   32	 * wall must cover. The archetype is deliberately not an input: two miners with the same band and the
   33	 * same planet state want the same wall.
   34	 *
   35	 * The need is a value, not a unit count: how many units a wall of this worth is stays the
   36	 * composition planner's business, because the doctrine's ratio and the host's prices live there.
   37	 */
   38	class DefenseNeedEvaluator
   39	{
   40	    /** Metal-equivalent weights, the same ones the rest of the module prices production with. */
   41	    private const CRYSTAL_WEIGHT = 1.5;
   42	
   43	    private const DEUTERIUM_WEIGHT = 2.0;
   44	
   45	    private const HOURS_PER_DAY = 24.0;
   46	
   47	    /**
   48	     * The value the wall must cover, or null when the planet already stands enough of it.
   49	     *
   50	     * The number a bare planet is given before exposure is weighed is the file's floor; the wall's own
   51	     * size stays the composition planner's business. Ships in orbit and the pile itself are part of
   52	     * the exposure, so a planet with nothing standing but something worth taking still wants a wall.
   53	     */
   54	    public function evaluate(PlayerService $player, PlanetService $planet): ?DefenseNeed
   55	    {
   56	        $profile = AiProfile::query()->where('player_id', $player->getId())->first();
   57	        if ($profile === null) {
   58	            return null;
   59	        }
   60	
   61	        $inbound = $this->inbound($player);
   62	
   63	        // The ceiling outranks the exposure clock: a planet that already holds the wall the
   64	        // behaviour file caps wants nothing further, whatever the account's production would pile
   65	        // up while it is away. Exposure is unbounded, and left to it the account builds the whole
   66	        // account's wall on one planet.
   67	        if ($this->atCeiling($planet)) {
   68	            return null;
   69	        }
   70	
   71	        // What piles up before the account next looks at the planet, what is standing on it, plus the
   72	        // pile itself once a hostile is on its way and spending it is no longer an option.
   73	        // A raider weighs what stands on the planet as much as what the mines pile up: hulls left in
   74	        // orbit and the solar satellites a planet keeps for power are carried away by the same attack,
   75	        // so they are part of the exposure the wall is sized to. The ships come from the host's own
   76	        // collection, so a satellite, a cargo hull and a warship are all counted at the host's price
   77	        // with no hull named here.
   78	        $exposure = $this->hourlyProduction($planet) * $this->absenceHours($profile->activity_band)
   79	            + $this->unitValue($planet->getShipUnits());
   80	        if ($inbound) {
   81	            $exposure += $this->metalEquivalent($planet->getResources());
   82	        }
   83	
   84	        // A planet with no defence at all takes the file's floor before exposure is weighed: a young
   85	        // colony's output is near zero, so exposure alone leaves it naked beside the walled planets
   86	        // the same account already holds (measured live 30 Sep 2026: 7-8 planets at zero defence while
   87	        // one held the wall). One wall unit's worth is all this says; the doctrine still sizes it.
   88	        if ($this->standingUnits($planet) === 0) {
   89	            $floor = $this->minimumDeterrent();
   90	            if ($floor !== null && $exposure < $floor->defenceValue) {
   91	                return $floor;
   92	            }
   93	        }
   94	
   95	        // A wall already worth at least this much wants nothing further; the two planners agree on
   96	        // the value through this comparison and nowhere else.
   97	        if ($exposure <= $this->unitValue($planet->getDefenseUnits())) {
   98	            return null;
   99	        }
  100	
  101	        return app()->makeWith(DefenseNeed::class, [
  102	            'defenceValue' => $exposure,
  103	            'reason' => 'defense:need:' . $this->contact($inbound),
  104	            'protectedValue' => $exposure,
  105	            'currentDefenseValue' => $this->unitValue($planet->getDefenseUnits()),
  106	            'threatBand' => $this->contact($inbound),
  107	            'intent' => $inbound ? 'reinforce' : 'hold',
  108	        ]);
  109	    }
  110	
  111	    /**
  112	     * Whether this planet already holds the wall the behaviour file caps, built or paid for in the
  113	     * yard. The yard counts because the host takes the whole price when the order is placed, so a
  114	     * planet with the ceiling queued has bought it (measured live: 50.8M paid but unbuilt units on
  115	     * grand while the planets read under the ceiling on built units alone).
  116	     */
  117	    private function atCeiling(PlanetService $planet): bool
  118	    {
  119	        $ceiling = $this->ceilingUnits();
  120	
  121	        if ($ceiling === null) {
  122	            return false;
  123	        }
  124	
  125	        return $this->standingUnits($planet) >= $ceiling;
  126	    }
  127	
  128	    /**
  129	     * The defence units this planet holds, built plus already ordered. Public because "this planet is
  130	     * still bare" is the question the unit planner asks before it spreads the account's wall orders:
  131	     * a planet whose first order is in the yard is no longer naked, so the next bare sibling gets the
  132	     * next order instead of the same planet taking every one (measured live 2 Oct 2026: one planet
  133	     * holding 21,084 units while 7-8 siblings sat at zero defence).
  134	     */
  135	    public function standingUnits(PlanetService $planet): int
  136	    {
  137	        return $planet->getDefenseUnits()->getAmount() + $this->pendingDefenseUnits($planet);
  138	    }
  139	
  140	    /**
  141	     * Defence this planet has paid for and is waiting on, from the host's own unit queue.
  142	     *
  143	     * The row is pending until the host credits the whole batch, so a planet with a wall in the
  144	     * yard reads as holding nothing until that batch lands.
  145	     */
  146	    private function pendingDefenseUnits(PlanetService $planet): int
  147	    {
  148	        $defenceObjectIds = array_map(
  149	            static fn ($object): int => $object->id,
  150	            ObjectService::getDefenseObjects()
  151	        );
  152	
  153	        if ($defenceObjectIds === []) {
  154	            return 0;
  155	        }
  156	
  157	        return (int) UnitQueue::query()
  158	            ->where('planet_id', $planet->getPlanetId())
  159	            ->whereIn('object_id', $defenceObjectIds)
  160	            ->where('processed', 0)
  161	            ->where('canceled', 0)
  162	            ->sum('object_amount');
  163	    }
  164	
  165	    /**
  166	     * The ceiling on one planet's wall from the behaviour file, or null when the file states none.
  167	     * The number is policy, so it lives there and not here; a file without it caps nothing.
  168	     *
  169	     * Built and paid-for units count together: the host takes the price when the order is placed.
  170	     */
  171	    private function ceilingUnits(): ?int
