uses(IsolatedAccountTestCase::class);

// The live read of invariant:NAKED_BESIDE_WALLED after the QUAL-DEDUP merge: an account that already
// holds a real wall on one planet must reach every bare sibling with its own logins. The cohort read
// (player 60) found three planets at zero built defence while one held 1,312 units, so this story
// gives the account a walled homeworld and three young colonies and lets its own day run.
test('a walled homeworld reaches every bare sibling in a day of logins', function (): void {
    $situation = Situation::of($this)
        ->resources(50_000_000, 50_000_000, 50_000_000)
        ->levelEveryPlanet('robot_factory', 2)
        ->levelEveryPlanet('shipyard', 4)
        ->defence('rocket_launcher', 1_300)
        ->colony()
        ->colony()
        ->colony()
        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000)
        ->day();

    expect(wallReachesBareSiblings($this->currentUserId))->toBe([], 'these planets hold no defence; ' . $situation->account());
});

/** @return list<int> planets (moons excluded) whose built defence columns are all zero */
function wallReachesBareSiblings(int $playerId): array
{
    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());

    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
        ->map(static fn ($id): int => (int) $id)
        ->filter(static function (int $id) use ($defence): bool {
            $planet = app(PlanetServiceFactory::class)->make($id, true);
            if ($planet === null) {
                return true;
            }

